#include <cmath>
#include <random>
#include <vector>

std::vector<double> terminal_prices(double s, double r, double sigma,
                                    double t, int n, unsigned seed) {
    std::mt19937 gen(seed);
    std::normal_distribution<double> z(0.0, 1.0);
    double drift = (r - 0.5 * sigma * sigma) * t;
    double vol = sigma * std::sqrt(t);
    std::vector<double> out(n);
    for (int i = 0; i < n; ++i) out[i] = s * std::exp(drift + vol * z(gen));
    return out;
}

