widget.solution:
#include <cmath>
#include <stdexcept>
#include <vector>

double mc_standard_error(const Payoff& p, double s, double r, double sigma,
                         double t, int n, unsigned seed) {
    if (n < 2) throw std::invalid_argument("need at least two paths");
    std::vector<double> st = terminal_prices(s, r, sigma, t, n, seed);
    double disc = std::exp(-r * t), mean = 0.0;
    for (double x : st) mean += disc * p(x);
    mean /= n;
    double ss = 0.0;
    for (double x : st) {
        double dev = disc * p(x) - mean;
        ss += dev * dev;
    }
    return std::sqrt(ss / (n - 1) / n);
}

