#include <cmath>
#include <random>

double mc_price_antithetic(const Payoff& p, double s, double r,
                           double sigma, double t, int n, unsigned seed) {
    std::mt19937 gen(seed);
    std::normal_distribution<double> z(0.0, 1.0);
    double drift = (r - 0.5 * sigma * sigma) * t, vol = sigma * std::sqrt(t);
    double sum = 0.0;
    for (int i = 0; i < n; ++i) {
        double e = z(gen);
        sum += 0.5 * (p(s * std::exp(drift + vol * e)) + p(s * std::exp(drift - vol * e)));
    }
    return std::exp(-r * t) * sum / n;
}

